use std::collections::HashMap
use std::fs

fn amt(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut m: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let a: int = amt(p[2])
            if a < 0 {
                println("error: invalid amount")
            } else if m.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                m.insert(p[1], a)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let a: int = amt(p[2])
            if a <= 0 {
                println("error: invalid amount")
            } else if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let bal: int = m.get(p[1]).copied().unwrap_or(0)
                if cmd == "deposit" {
                    m.insert(p[1], bal + a)
                    println("ok")
                } else if bal < a {
                    println("error: insufficient funds")
                } else {
                    m.insert(p[1], bal - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let a: int = amt(p[3])
            if a <= 0 {
                println("error: invalid amount")
            } else if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !m.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let fb: int = m.get(p[1]).copied().unwrap_or(0)
                let tb: int = m.get(p[2]).copied().unwrap_or(0)
                if fb < a {
                    println("error: insufficient funds")
                } else {
                    m.insert(p[1], fb - a)
                    m.insert(p[2], tb + a)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let b: int = m.get(p[1]).copied().unwrap_or(0)
                println("${b}")
            }
        }
    }
    let mut keys: Vec<string> = m.keys().map(|k| k.clone()).collect()
    keys.sort()
    for k in keys {
        let b: int = m.get(k).copied().unwrap_or(0)
        println("${k} ${b}")
    }
}

